import { useEffect, useMemo, useState } from 'react';
import { ArrowLeft, Download, Pencil, RefreshCw } from 'lucide-react';
import { createExternalClientInvitation, downloadExternalClientDocument, getCurrentExternalClientInvitation, getExternalClient360, regenerateExternalClientInvitation, revokeExternalClientInvitation, updateExternalClient360 } from '../../lib/fiteatsyConsultantsApi';

const tabs = ['Overview', 'Health Profile', 'Nutrition', 'Measurements', 'Reports', 'Timeline'];
const groups = {
  'Health Profile': ['medicalHistory', 'conditionsSymptoms', 'allergiesFamilyHistory', 'medicationsSupplements', 'lifestyle', 'sleepStress', 'activityHydration', 'womensHealth'],
  Nutrition: ['nutrition', 'goals'],
  Measurements: ['measurements'],
};
const title = (value) => value.replace(/([A-Z])/g, ' $1').replace(/^./, (letter) => letter.toUpperCase());
const show = (value) => Array.isArray(value) ? value.join(', ') || 'Not provided' : typeof value === 'object' && value !== null ? JSON.stringify(value) : value === null || value === undefined || value === '' ? 'Not provided' : String(value);

function Provenance({ value }) { return <span className="ml-2 rounded-full bg-slate-100 px-2 py-0.5 text-[10px] font-semibold text-slate-500">{value || 'Self-reported'}</span>; }
function SectionCard({ section, values, provenance, onEdit }) {
  return <section className="rounded-2xl border border-slate-200 bg-white p-5 shadow-sm"><div className="flex items-center justify-between"><h3 className="font-semibold">{title(section)}</h3><button onClick={() => onEdit(section, values)} className="inline-flex items-center gap-1.5 rounded-lg border border-slate-200 px-3 py-1.5 text-xs font-semibold"><Pencil size={13}/>Edit</button></div>{!values || Object.keys(values).length === 0 ? <p className="mt-4 text-sm text-slate-500">Not provided</p> : <dl className="mt-4 grid gap-3 sm:grid-cols-2">{Object.entries(values).map(([key, value]) => <div key={key} className="rounded-xl bg-slate-50 p-3"><dt className="text-xs font-medium text-slate-500">{title(key)}<Provenance value={provenance?.[key]?.sourceLabel || provenance?.sourceLabel}/></dt><dd className="mt-1 break-words text-sm font-medium">{show(value)}</dd></div>)}</dl>}</section>;
}

export function ExternalClient360({ client, onBack, onStatus }) {
  const [data, setData] = useState(null); const [active, setActive] = useState('Overview'); const [error, setError] = useState(''); const [loading, setLoading] = useState(true); const [editing, setEditing] = useState(null);
  const [invitation, setInvitation] = useState(null); const [shareUrl, setShareUrl] = useState('');
  const load = async () => { setLoading(true); setError(''); try { const result = await getExternalClient360(client.id); setData(result.client360); } catch (requestError) { setError(requestError.message || 'Unable to load Client 360.'); } finally { setLoading(false); } };
  useEffect(() => { void load(); getCurrentExternalClientInvitation(client.id).then((result) => setInvitation(result.invitation)).catch(() => setInvitation(null)); }, [client.id]);
  const overview = data?.overview;
  const edit = (section, values) => setEditing({ section, text: JSON.stringify(values || {}, null, 2) });
  const save = async () => { try { const values = JSON.parse(editing.text); const result = await updateExternalClient360(client.id, editing.section, values); setData(result.client360); setEditing(null); } catch (saveError) { setError(saveError.message || 'Unable to save changes.'); } };
  const issueInvitation = async () => { try { const result = await (invitation ? regenerateExternalClientInvitation(client.id) : createExternalClientInvitation(client.id)); setInvitation(result.invitation); setShareUrl(result.shareUrl); } catch (requestError) { setError(requestError.message || 'Unable to create invitation.'); } };
  const revokeInvitation = async () => { try { const result = await revokeExternalClientInvitation(client.id); setInvitation(result.invitation); setShareUrl(''); } catch (requestError) { setError(requestError.message || 'Unable to revoke invitation.'); } };
  const visibleSections = useMemo(() => groups[active] || [], [active]);
  return <section>
    <button onClick={onBack} className="mb-5 inline-flex items-center gap-2 text-sm font-semibold text-slate-600"><ArrowLeft size={17}/>Back to clients</button>
    {error && <div role="alert" className="mb-4 rounded-xl bg-red-50 px-4 py-3 text-sm text-red-700">{error}</div>}
    {loading ? <div className="rounded-2xl bg-white p-12 text-center text-sm text-slate-500">Loading Client 360…</div> : data ? <>
      <header className="rounded-2xl border border-slate-200 bg-white p-6 shadow-sm"><div className="flex flex-col justify-between gap-5 md:flex-row"><div><p className="text-sm text-slate-500">Client 360</p><h2 className="mt-1 text-3xl font-semibold">{overview.name}</h2><p className="mt-2 text-sm text-slate-600">{[overview.age && `${overview.age} years`, overview.gender?.replaceAll('_', ' '), overview.primaryContact].filter(Boolean).join(' · ')}</p></div><div className="flex items-start gap-2"><button onClick={load} aria-label="Refresh Client 360" className="rounded-xl border border-slate-200 p-2.5"><RefreshCw size={17}/></button><select value={overview.status} onChange={async (event) => { await onStatus(event.target.value); await load(); }} className="h-11 rounded-xl border border-slate-200 px-3">{['INVITED','INTAKE_STARTED','INTAKE_COMPLETED','ACTIVE','INACTIVE'].map((value) => <option key={value}>{value}</option>)}</select></div></div><div className="mt-6 grid gap-3 sm:grid-cols-4"><Summary label="Completeness" value={`${overview.profileCompleteness}%`}/><Summary label="Primary goal" value={overview.primaryGoal || 'Not provided'}/><Summary label="Diet preference" value={overview.dietPreference || 'Not provided'}/><Summary label="Documents" value={overview.documentCount}/></div>{overview.missingSections.length > 0 && <p className="mt-4 text-xs text-amber-700">Missing: {overview.missingSections.map(title).join(', ')}</p>}</header>
      <nav className="my-5 flex gap-2 overflow-x-auto" aria-label="Client 360 sections">{tabs.map((tab) => <button key={tab} onClick={() => setActive(tab)} className={`whitespace-nowrap rounded-full px-4 py-2 text-sm font-semibold ${active === tab ? 'bg-slate-950 text-white' : 'bg-white text-slate-600'}`}>{tab}</button>)}</nav>
      {active === 'Overview' && <div className="grid gap-4 lg:grid-cols-2"><SectionCard section="basicProfile" values={Object.fromEntries(Object.entries(data.basicProfile).map(([key, item]) => [key, item.value]))} provenance={Object.fromEntries(Object.entries(data.basicProfile).map(([key, item]) => [key, item]))} onEdit={edit}/><div className="space-y-4"><section className="rounded-2xl border border-slate-200 bg-white p-5"><h3 className="font-semibold">Consent status</h3><p className="mt-3 text-sm">{data.consent.status}</p><p className="mt-1 text-xs text-slate-500">{data.consent.consentedAt ? new Date(data.consent.consentedAt).toLocaleString() : 'Consent has not been recorded.'}</p>{data.derived.bmi && <div className="mt-5 rounded-xl bg-slate-50 p-3"><p className="text-xs text-slate-500">BMI <Provenance value={data.derived.bmi.sourceLabel}/></p><p className="mt-1 text-lg font-semibold">{data.derived.bmi.value}</p></div>}</section><section className="rounded-2xl border border-slate-200 bg-white p-5"><h3 className="font-semibold">Health-profile invitation</h3><p className="mt-2 text-sm text-slate-500">{invitation ? invitation.status.replaceAll('_', ' ') : 'Not invited'}</p><div className="mt-4 flex flex-wrap gap-2"><button onClick={issueInvitation} className="rounded-xl bg-slate-950 px-4 py-2 text-sm font-semibold text-white">{invitation ? 'Regenerate' : 'Invite client'}</button>{invitation && ['PENDING','OPENED'].includes(invitation.status) && <button onClick={revokeInvitation} className="rounded-xl border border-red-200 px-4 py-2 text-sm font-semibold text-red-700">Revoke</button>}{shareUrl && <button onClick={() => navigator.clipboard.writeText(shareUrl)} className="rounded-xl border border-slate-200 px-4 py-2 text-sm font-semibold">Copy secure link</button>}</div></section></div></div>}
      {visibleSections.length > 0 && <div className="grid gap-4 lg:grid-cols-2">{visibleSections.filter((section) => section !== 'womensHealth' || overview.gender === 'FEMALE').map((section) => <SectionCard key={section} section={section} values={data.sections[section]} provenance={data.provenance[section]} onEdit={edit}/>)}</div>}
      {active === 'Reports' && <div className="space-y-3">{data.documents.length === 0 ? <Empty text="No reports or documents uploaded."/> : data.documents.map((document) => <div key={document.id} className="flex items-center justify-between rounded-2xl border border-slate-200 bg-white p-4"><div><p className="font-semibold">{document.name}</p><p className="mt-1 text-xs text-slate-500">{document.category} · {document.sourceLabel} · {new Date(document.uploadedAt).toLocaleString()}</p></div><button onClick={() => downloadExternalClientDocument(client.id, document.id, document.name)} className="rounded-xl border border-slate-200 p-2.5" aria-label={`Download ${document.name}`}><Download size={17}/></button></div>)}</div>}
      {active === 'Timeline' && <div className="space-y-3">{data.timeline.length === 0 ? <Empty text="No operational history yet."/> : data.timeline.map((event, index) => <div key={`${event.occurredAt}-${index}`} className="rounded-2xl border border-slate-200 bg-white p-4"><p className="font-semibold">{title(event.type.toLowerCase())}</p><p className="mt-1 text-xs text-slate-500">{event.category} · {new Date(event.occurredAt).toLocaleString()}</p></div>)}</div>}
    </> : null}
    {editing && <div className="fixed inset-0 z-50 grid place-items-center bg-slate-950/40 p-4"><div className="w-full max-w-xl rounded-2xl bg-white p-6"><h3 className="text-lg font-semibold">Edit {title(editing.section)}</h3><p className="mt-1 text-xs text-slate-500">Values are preserved as Consultant-entered history.</p><textarea aria-label="Section values" rows={14} value={editing.text} onChange={(event) => setEditing({ ...editing, text: event.target.value })} className="mt-4 w-full rounded-xl border border-slate-200 p-3 font-mono text-sm"/><div className="mt-4 flex justify-end gap-2"><button onClick={() => setEditing(null)} className="rounded-xl border border-slate-200 px-4 py-2 text-sm font-semibold">Cancel</button><button onClick={save} className="rounded-xl bg-slate-950 px-4 py-2 text-sm font-semibold text-white">Save changes</button></div></div></div>}
  </section>;
}
function Summary({ label, value }) { return <div className="rounded-xl bg-slate-50 p-3"><p className="text-xs text-slate-500">{label}</p><p className="mt-1 truncate font-semibold">{show(value)}</p></div>; }
function Empty({ text }) { return <div className="rounded-2xl border border-dashed border-slate-300 bg-white p-10 text-center text-sm text-slate-500">{text}</div>; }
